// The homepage sentence bloom, ported from the Tongan site: lea-faka-tonga-app src/premium/lib/blueprint/sentence-bloom.js at
// 4f1fb7e (the 2026-10-09 middle, approved there). Its data is src/data/sentence-bloom.json, generated by
// scripts/build-sentence-bloom.mjs from scripts/sentence-bloom-spec.json and the synced book, never edited by hand.
// Changes in the port, and only these: the data and its import (the Samoan play; 51 chapters in three levels); "Chapter" for
// "Lesson" in every visible string, and /chapters/N links; lang="sm" for lang="to"; Samoan inside an English title or topic is
// the book's own *italics* (as the site's Inline component reads it), not a term list, so okinafy and the Tongan term list are
// gone; the page chapter, its neighbours, the chapters dimmed behind it and the chapter count come from the data instead of 9,
// 8 to 10, 1 to 8 and 52; the drum room that shrinks in the morph after the last three-word spin is found by position instead
// of a Tongan row id; on desktop a level longer than twelve chapters wraps into balanced rows; the road under the sentence runs
// to one past the page chapter, and its numbered stops are the chapters the play draws on.
// Sentence bloom for the homepage: a 32 s play that ends on the whole course, explorable chapter by chapter.
// 0 to 19.45 s: one sentence spins its tense, its verb and its person, grows a describing verb and a doer, takes the not-word, then
// a place, time words and a companion (scripts/sentence-bloom-spec.json). Then the page chapter's page (Chapter 20) holds, the
// camera pulls back until the page is its chip on the course's own road; chips 19, 20 and 21 hold with their titles; the camera
// widens to the course view's framing while a band opens above the map; a stroke walks the road to 51, resting at four later
// chapters (24, 27, 36 and 45) while each one's sentence shows in the band in the play's own type, linked to its chip
// (reviews/2026-10-24-sentence-bloom/Ending-Storyboard.md, direction B); the road turns blueprint blue in place and is the
// course view (the three levels). The numbers come from the data.
// Self-contained ES module, no dependencies. mount(element, options) returns a controller; unmount() removes it.
// Look: the homepage's own tokens (--wr-*, --f-*, base.css), whose accent is the course blue; the blueprint keeps its ruled
// palette (#0d375c, #c4deff, #deecff). Every Samoan string comes from ./sentence-bloom.json (sentences printed with their English
// in their chapter, and labels from the sections that name them); chapter titles, levels and sections come from chapters.json.
import DATA from '@app/data/sentence-bloom.json'

// Development only: freeze the imported data, so any write into it throws instead of leaking state between mounts.
const DEV = (() => { try { if (import.meta.env) return !!import.meta.env.DEV } catch { /* not bundled */ } return typeof location !== 'undefined' && /^(localhost|127\.0\.0\.1)$/.test(location.hostname) })()
const deepFreeze = o => { if (o && typeof o === 'object' && !Object.isFrozen(o)) { Object.freeze(o); for (const v of Object.values(o)) deepFreeze(v) } return o }
if (DEV) deepFreeze(DATA)

const ROWS = DATA.rows, LESSONS = DATA.lessons, PLAY = DATA.play, COURSE = DATA.course
const PAGE = PLAY.page
// the page chapter (where the play ends) and the course's last chapter
const PN = PLAY.pageLesson, LAST = LESSONS.length
const BP = '#0d375c', RING = '#c4deff', BPINK = '#deecff'
const clamp = (x, a = 0, b = 1) => Math.max(a, Math.min(b, x))
const lerp = (a, b, e) => a + (b - a) * e
const E = u => 1 - Math.pow(1 - clamp(u), 2.4)
const smooth = u => { u = clamp(u); return u * u * (3 - 2 * u) }
const span = (a, b, t) => clamp((t - a) / (b - a))
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c])
const h = (tag, cls, html) => { const e = document.createElement(tag); if (cls) e.className = cls; if (html != null) e.innerHTML = html; return e }
const srcText = i => (i == null ? '' : DATA.sources[i].replace(/^book\/Chapter-0?(\d+)\.md:[\d,-]+ \| /, 'Chapter $1: '))
// Samoan inside an English title or topic is in the book's *italics* (chapters.json keeps the markup). It is set lang="sm" with
// the site's Samoan class, and straight double quotes print curly, as the site's Inline component (components/T.jsx) does.
const mixedHtml = text => String(text ?? '').replace(/"([^"]*)"/g, '\u201c$1\u201d').split(/\*([^*]+)\*/).map((part, i) => (i % 2 ? `<span lang="sm" class="to">${esc(part)}</span>` : esc(part))).join('')
const plainTitle = text => String(text ?? '').replace(/\*+/g, '')
const COUNT = ['no', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight']
const GROUP = Object.fromEntries(COURSE.groups.map(g => [g.key, g.name]))

// The beat table the module plays: the sentence's beats (Storyboard.json), then the ending (reviews/bloom-middle-2026-10-09/Storyboard-Final.json).
const SEG_BEATS = (() => {
  const out = []
  for (const s of PLAY.segs) { const l = out[out.length - 1]; if (l && l.id === s.beat) l.end = s.t1; else out.push({ id: s.beat, start: s.t0, end: s.t1 }) }
  return out
})()
const timelineOf = ending => Object.freeze([...SEG_BEATS, ...ending].map(b => Object.freeze({ id: b.id, start: b.start, end: b.end })))
export const TIMELINE = timelineOf(PLAY.ending)
// The pacing bench (reviews/bloom-middle-2026-10-09/bench/, never part of the site) re-times the middle with mount(el, { ending });
// the homepage never passes it. It carries the data's ending beats, the same ids in the same order, contiguous from the page beat.
function endingOf(given) {
  if (given == null) return PLAY.ending
  const ids = PLAY.ending.map(b => b.id)
  if (!Array.isArray(given) || given.length !== ids.length) throw new Error(`ending: ${ids.length} beats expected`)
  let at = PAGE
  return Object.freeze(given.map((b, i) => {
    const start = +b.start, end = +b.end
    if (b.id !== ids[i]) throw new Error(`ending: beat ${i + 1} is ${b.id}, expected ${ids[i]}`)
    if (!(Math.abs(start - at) < 1e-6 && end > start)) throw new Error(`ending: ${b.id} does not follow on from ${at} s`)
    at = end
    return Object.freeze({ id: b.id, start, end })
  }))
}

// the middle: the chapters held with their title under the chip (hold-N beats), the chapters whose sentence shows in the band
// (say-N beats, each with its row from PLAY.says), the chapters already behind the page chapter's chip (accent, dim), and the three
// chapters read by title while the camera holds on them
const HOLDS = PLAY.ending.filter(b => /^hold-\d+$/.test(b.id)).map(b => +b.id.slice(5))
const SAYS = PLAY.ending.filter(b => /^say-\d+$/.test(b.id)).map(b => { const n = +b.id.slice(4); return { id: b.id, n, row: PLAY.says.find(s => s.lesson === n).row } })
const DIM_TO = PN - 1, DIM_OP = 0.45, NEIGHBOURS = [PN - 1, PN, PN + 1]
// a say beat's last LEAD seconds walk the stroke on to the next say's chapter, so reading and walking overlap; ROLL is how long a
// sentence takes to roll into the band (the play's English roll)
const LEAD = 0.5, ROLL = 0.35
// a chip's look on the white ground: background, ring, number, and the extra ring drawn inside its 1.5 px border (2 px ahead, 3 px ringed)
const LOOK = { ahead: ['#fff', 'var(--line-strong,#d3cdc4)', 'var(--wr-muted)', 0.5], done: ['var(--wr-red)', 'var(--wr-red)', '#fff', 0], cur: ['#fff', 'var(--wr-red)', 'var(--wr-red-deep)', 1.5] }
const mixC = (a, b, k) => (k <= 0.001 ? a : k >= 0.999 ? b : `color-mix(in srgb, ${b} ${(k * 100).toFixed(1)}%, ${a})`)

