      path += `<path style="opacity:${(0.9 * lo).toFixed(3)}" d="M${x1.toFixed(1)} ${y1.toFixed(1)} C ${x1.toFixed(1)} ${my.toFixed(1)}, ${p.x.toFixed(1)} ${my.toFixed(1)}, ${p.x.toFixed(1)} ${y2.toFixed(1)}"/>`
